import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedInputStream in = new BufferedInputStream(System.in);

        int k = nextInt(in);
        int n = nextInt(in);
        boolean[] allowed = new boolean[128];

        String alphabet = nextToken(in);
        for (int i = 0; i < k; i++) {
            allowed[alphabet.charAt(i)] = true;
        }

        String message = nextToken(in);
        for (int i = 0; i < n; i++) {
            if (!allowed[message.charAt(i)]) {
                System.out.println("N");
                return;
            }
        }

        System.out.println("S");
    }

    private static int nextInt(BufferedInputStream in) throws IOException {
        return Integer.parseInt(nextToken(in));
    }

    private static String nextToken(BufferedInputStream in) throws IOException {
        StringBuilder token = new StringBuilder();
        int c;

        do {
            c = in.read();
        } while (c <= 32 && c != -1);

        while (c > 32 && c != -1) {
            token.append((char) c);
            c = in.read();
        }

        return token.toString();
    }
}
